mapper.select:
SELECT * FROM exam_question
WHERE subject_id=#{subjectId}
ORDER BY id DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE exam_question
type=#{type}, stem=#{stem}, options_json=#{optionsJson}, answer_key=#{answerKey}, score=#{score}, subject_id=#{subjectId}, explain_text=#{explainText},
WHERE id=#{id}

UPDATE exam_paper
title=#{title}, duration_min=#{durationMin}, status=#{status}, subject_id=#{subjectId}, max_attempts=#{maxAttempts},
WHERE id=#{id}

mapper.select:
SELECT * FROM exam_attempt
WHERE paper_id=#{paperId}
ORDER BY id DESC LIMIT #{limit} OFFSET #{offset}

SELECT w.*, q.stem AS stem, q.type AS type, q.score AS score
FROM exam_wrongbook w
LEFT JOIN exam_question q ON q.id = w.question_id
WHERE w.username=#{username}
ORDER BY w.id DESC LIMIT #{limit} OFFSET #{offset}
